/* Install gallery: slow continuous scroll, two rows in opposite directions */
@keyframes hg-scroll{from{transform:translate3d(0,0,0)}to{transform:translate3d(-50%,0,0)}}
.home-gallery_track{animation:hg-scroll 90s linear infinite;will-change:transform;}
.home-gallery_row[data-direction="reverse"] .home-gallery_track{animation-direction:reverse;animation-duration:100s;}
.home-gallery_marquee:hover .home-gallery_track{animation-play-state:paused;}
@media (max-width:767px){.home-gallery_track{animation-duration:70s;}.home-gallery_row[data-direction="reverse"] .home-gallery_track{animation-duration:78s;}}
@media (prefers-reduced-motion:reduce){
.home-gallery_track{animation:none;}
.home-gallery_row{overflow-x:auto;scrollbar-width:none;}
.home-gallery_row::-webkit-scrollbar{display:none;}
}


