.section_faqs .dropdown_faqs-content .text-size-regular{font-size:1.0625rem;line-height:1.65;opacity:.8;max-width:38rem;}
@media (max-width:767px){
.main-wrapper .text-size-regular{font-size:1.0625rem;}
.section_home-services .text-size-large{font-size:1.25rem !important;}
.section_faqs .faqs_list{gap:.625rem;}
