function services() {
  let splideElement = document.querySelector('#services'); // Usar ID único

  if (!splideElement) return; // Salir si no encuentra el ID

  const splide = new Splide(splideElement, {
    type: 'slide', // Tipo de desplazamiento
    perPage: "auto", // Mostrar solo 1 slide a la vez
    arrows: false, // Deshabilitar las flechas de Splide
    pagination: true, // Mantener paginación
    drag: true, // Habilitar desplazamiento manual
    pauseOnHover: false,
    pauseOnFocus: false,
    gap: '1rem',
    autoWidth: true, // Deshabilitar ancho automático
    focus: 'start', // Centrar el slide activo
    breakpoints: {
      1320: { gap: '1rem' },
      1080: { gap: '1rem' },
      992: {},
      780: { gap: '1rem', focus: 'center' },
    },
  });

  splide.mount();

  // Configuración de las flechas personalizadas
  const customPrev = document.querySelector('.services-btn-prev');
  const customNext = document.querySelector('.services-btn-next');

  if (customPrev && customNext) {
    customPrev.addEventListener('click', function () {
      splide.go('<'); // Mover al slide anterior
    });
    customNext.addEventListener('click', function () {
      splide.go('>'); // Mover al siguiente slide
    });
  }
}

// Llamamos a la función correctamente
services();

